            if not name.endswith('.treefile'): continue
            txt=z.read(name).decode()
            try:
                n,total,internal,terminal,t,leaves=metrics(txt)
            except Exception as e:
                missing.append((name,str(e),txt[:200]))
                continue
            vals.append((name,t,n,total,internal,terminal,leaves,txt.strip()))
            taxa_counts[n]+=1
            shapes[tuple(sorted(leaves))]+=1
    ts=sorted(v[1] for v in vals)
