    print('median',statistics.median(ts),'mean',statistics.mean(ts),'min',min(ts),'max',max(ts))
    print('quartiles',statistics.quantiles(ts,n=4,method='inclusive'))
    print('zeros',sum(v==0 for v in ts),'nan',sum(math.isnan(v) for v in ts))
    print('first_sorted')
    for row in sorted(vals,key=lambda x:x[1])[:5]: print(row[:6],row[7])
    print('last_sorted')
    for row in sorted(vals,key=lambda x:x[1])[-5:]: print(row[:6],row[7])
    if missing: print('errors',missing[:3])
